// A/B xen kẽ trên GPU thật: mỗi cấu hình đo nhiều vòng, lấy trung vị. node ab.mjs <repo> [--w= --h=] [--night] [--view=bridge,view]
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const repo = process.argv[2];
const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
const W = +arg('w', 1920), H = +arg('h', 1080), night = process.argv.includes('--night'), view = arg('view', '');
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(path.join(repo, 'dist'));
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page, errors } = await lib.openApp(browser, srv.url, { width: W, height: H });
try {
  if (view) { const [b, v] = view.split(','); await lib.pickView(page, b, v); }
  if (night) { await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 1; }); }
  await lib.frames(page, 10);
  const res = await page.evaluate(async (night) => {
    const A = window.__app, R = A.renderer, gl = R.getContext(), px = new Uint8Array(4);
    const byName = (n) => { const l = []; A.scene.traverse((o) => { if (o.name === n && o.isMesh) l.push(o); }); return l; };
    const composer = null;
    const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
    const ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
    if (!ext) return { 'không có timer query': {} };
    const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
    const t = async (n = 12) => {
      draw(); draw();
      const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
      for (let i = 0; i < n; i++) draw();
      gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
      for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
      const ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
      return ns / 1e6 / n;
    };
    // lưới ẩn riêng trong lượt phản chiếu: bọc onBeforeRender của nước
    const water = A.scene.children.find((o) => o.material?.uniforms?.mirrorSampler);
    const wDraw = water.onBeforeRender; let hideInMirror = [];
    water.onBeforeRender = function (...a) { for (const o of hideInMirror) o.visible = false; wDraw.apply(this, a); for (const o of hideInMirror) o.visible = true; };
    const crown = byName('trees-shade-crown'), trunk = byName('trees-shade-trunk'), palmC = byName('trees-palm-crown'), palmT = byName('trees-palm-trunk'), cars = byName('traffic-city'), boats = byName('boats-river');
    const trees = [...crown, ...trunk, ...palmC, ...palmT];
    const all = []; A.scene.traverse((o) => { if (o.isMesh) all.push(o); });
    const shadowOff = (l) => { const s = l.map((o) => o.castShadow); l.forEach((o) => (o.castShadow = false)); return () => l.forEach((o, i) => (o.castShadow = s[i])); };
    const hide = (l) => { l.forEach((o) => (o.visible = false)); return () => l.forEach((o) => (o.visible = true)); };
    const lights = []; A.scene.traverse((o) => { if (o.isPointLight) lights.push(o); });
    const lightsOff = () => { lights.forEach((l) => (l.visible = false)); return () => lights.forEach((l) => (l.visible = true)); };
    const both = (...f) => () => { const u = f.map((x) => x()); return () => u.forEach((x) => x()); };
    const noShadow = () => { stop = true; return () => (stop = false); };
    let stop = false; const ss = R.shadowMap; let au = true; Object.defineProperty(ss, 'autoUpdate', { get: () => !stop && au, set: (v) => (au = v) });
    const noMirror = () => { A.reflectState.every = 0; return () => (A.reflectState.every = 1); };
    const cfgs = {
      'gốc': () => () => {},
      'bỏ PointLight': lightsOff,
      'tắt bóng': noShadow,
      'tắt phản chiếu': noMirror,
      'tắt bóng + phản chiếu': both(noShadow, noMirror),
      'cây: bỏ khỏi phản chiếu': () => { hideInMirror = trees; return () => (hideInMirror = []); },
      'cây: không đổ bóng': () => shadowOff(trees),
      'xe phố: không đổ bóng': () => shadowOff(cars),
      'cây: ẩn hẳn': () => hide(trees),
      'xe phố: ẩn hẳn': () => hide(cars),
      'ẩn nước': () => hide([water]),
      'bỏ PointLight + tắt bóng + phản chiếu': both(lightsOff, noShadow, noMirror),
      'bỏ PointLight + cây khỏi phản chiếu + xe không bóng': both(lightsOff, () => { hideInMirror = trees; return () => (hideInMirror = []); }, () => shadowOff(cars))
    };
    const out = {}, tri = {};
    for (const k in cfgs) out[k] = [];
    for (let round = 0; round < 5; round++) for (const k in cfgs) {
      const undo = cfgs[k](); await t(3);
      out[k].push(await t(12)); tri[k] = [R.info.render.calls, R.info.render.triangles];
      undo();

    }
    const med = (a) => a.slice().sort((x, y) => x - y)[a.length >> 1];
    const rows = {};
    for (const k in out) rows[k] = { ms: +med(out[k]).toFixed(2), min: +Math.min(...out[k]).toFixed(2), max: +Math.max(...out[k]).toFixed(2), calls: tri[k][0], tris: tri[k][1] };
    return rows;
  }, night);
  console.log(`khung ${W}x${H} ${night ? 'ĐÊM' : 'ngày'} ${view}`);
  console.table(res);
  if (errors.length) console.log('LỖI console:', errors);
} finally { await browser.close(); srv.close(); }

