// Đo biên dịch nền bộ đèn trên GPU thật: node bgwarm.mjs <repo> <distDir> <query>   (query vd "perf&lightsets=bg", "perf")
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const repo = process.argv[2], dist = process.argv[3], query = process.argv[4] || 'perf';
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page, errors } = await lib.openApp(browser, srv.url + '?' + query, { width: 1920, height: 1080 });
const J = (x) => JSON.stringify(x);
try {
  const st = await page.evaluate(() => ({ firstFrameMs: Math.round(window.__app.perf.firstFrameMs), programs: window.__app.renderer.info.programs.length, set: window.__app.lights?.set, mode: window.__app.lights?.mode, ext: !!window.__app.renderer.extensions.has('KHR_parallel_shader_compile') }));
  console.log('khởi động', J(st));
  // ghi mỗi khung: khoảng cách, bộ đèn, số program
  await page.evaluate(() => {
    const A = window.__app; const rec = (window.__rec = []); let last = performance.now();
    const f = () => { const t = performance.now(); rec.push([t - last, A.lights?.set, A.renderer.info.programs.length, A.lights?.ready?.day, A.lights?.ready?.night, t]); last = t; requestAnimationFrame(f); };
    requestAnimationFrame(f); A.perf.reset();
  });
  const take = () => page.evaluate(() => { const r = window.__rec.slice(); window.__rec.length = 0; return r; });
  const summary = (label, r) => {
    const dts = r.map((x) => x[0]); const max = Math.max(...dts); const sorted = dts.slice().sort((a, b) => a - b);
    const long = r.filter((x) => x[0] > 50).map((x) => `${x[0].toFixed(0)}ms@${x[1]}/p${x[2]}`);
    console.log(`${label.padEnd(26)} khung ${r.length}, trung vị ${sorted[sorted.length >> 1]?.toFixed(1)} ms, dài nhất ${max.toFixed(1)} ms, program ${r[0]?.[2]}→${r.at(-1)?.[2]}; khung > 50 ms: ${long.slice(0, 12).join(' ')}`);
  };
  const setNight = (n) => page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
  const hasSets = st.mode !== undefined;
  if (query.includes('lightsets=bg')) {
    const t0 = await page.evaluate(() => performance.now());
    const tDay = await page.waitForFunction(() => window.__app.lights.ready.day && performance.now(), null, { timeout: 120000, polling: 50 }).then((h) => h.jsonValue());
    const tNight = await page.waitForFunction(() => window.__app.lights.ready.night && performance.now(), null, { timeout: 120000, polling: 50 }).then((h) => h.jsonValue());
    await lib.frames(page, 20);
    const r = await take();
    const iDay = r.findIndex((x) => x[1] === 'day');
    const warmPart = r.filter((x) => x[5] < tNight - 0);
    summary('hâm nền (tới ready.night)', warmPart);
    console.log(`ready.day sau ${(tDay - t0).toFixed(0)} ms, ready.night sau ${(tNight - t0).toFixed(0)} ms (tính từ lúc mở trang xong); perf.maxs:`, J(await page.evaluate(() => window.__app.perf.maxs)));
    if (iDay >= 0) summary('chuyển full→day lần đầu', r.slice(Math.max(0, iDay - 1), iDay + 15)); else console.log('chưa chuyển sang day!');
    summary('sau ready (20 khung)', r.slice(-20));
  } else { await lib.frames(page, 120); summary('120 khung đầu sau mở', await take()); }
  await page.evaluate(() => window.__app.perf.reset());
  const step = async (label, fn, n = 30) => { await take(); await fn(); await lib.frames(page, n); const r = await take(); summary(label, r); return r; };
  await step('đêm lần đầu', () => setNight(1));
  await step('ngày lần 2', () => setNight(0));
  await step('đêm lần 2', () => setNight(1));
  await step('ngày lần 3', () => setNight(0));
  await step('bay Thuận Phước (ngày)', () => lib.pickView(page, 'tp', 'tpBay'), 10);
  await lib.frames(page, 30);
  await step('về Cầu Rồng overview', () => lib.pickView(page, 'dragon', 'overview'), 10);
  console.log('perf.maxs:', J(await page.evaluate(() => window.__app.perf.maxs)));
  // lệnh vẽ + bộ đèn góc mặc định (gọi lại góc mặc định khó: dùng overview như perf-check) — ngày / đêm
  const info = async () => { await lib.frames(page, 8); return page.evaluate(() => ({ set: window.__app.lights?.set, calls: window.__app.renderer.info.render.calls, tris: window.__app.renderer.info.render.triangles, programs: window.__app.renderer.info.programs.length })); };
  await setNight(0); console.log('overview ngày', J(await info()));
  await setNight(1); console.log('overview đêm', J(await info()));
  await setNight(0);
  if (hasSets && st.mode !== 'off') {
    const gpu = () => page.evaluate(async () => {
      const A = window.__app, R = A.renderer, gl = R.getContext();
      const ext = gl.getExtension('EXT_disjoint_timer_query_webgl2'); if (!ext) return -1;
      const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
      const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
      draw(); draw();
      const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
      for (let i = 0; i < 12; i++) draw();
      gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
      for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
      const ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
      return ns / 1e6 / 12;
    });
    const force = (full) => page.evaluate((full) => { const L = window.__app.lights; L.ready.day = L.ready.night = !full; }, full);
    const out = {};
    for (let r = 0; r < 5; r++) for (const n of [0, 1]) for (const full of [false, true]) {
      await force(full); await setNight(n); await lib.frames(page, 8);
      const k = `${n ? 'đêm' : 'ngày'} ${full ? 'ép full' : 'bộ thật'}`;
      (out[k] ||= []).push([await gpu(), await page.evaluate(() => window.__app.lights.set)]);
    }
    await force(false);
    const med = (a) => a.map((x) => x[0]).sort((x, y) => x - y)[a.length >> 1];
    for (const k in out) console.log(`GPU ${k.padEnd(14)} trung vị ${med(out[k]).toFixed(2)} ms (bộ ${out[k][0][1]})`);
  }
  console.log('program cuối', await page.evaluate(() => window.__app.renderer.info.programs.length));
  if (errors.length) console.log('LỖI console:', errors);
} finally { await browser.close(); srv.close(); }

