1	import * as THREE from 'three';
2	import { CONFIG } from '../config';
3	import { scene, renderer } from './renderer';
4	import { deckY } from '../bridges/dragon/profile';
5	import { device } from './device';
6	
7	/* ============================ Ánh sáng ============================ */
8	export const sun = new THREE.DirectionalLight(0xfff1dc, 3.0);
9	export const hemi = new THREE.HemisphereLight(0xcfe6ff, 0x6b6a55, 0.9);
10	export const moon = new THREE.DirectionalLight(0x8fa8ff, 0);
11	export const bridgeLights: THREE.PointLight[] = [];
12	export let fireLight: THREE.PointLight;
13	/* 6 đèn Cầu Rồng + đèn lửa chung một nhóm ở gốc tọa độ (vị trí thế giới = vị trí riêng): bộ đèn (D-031) ẩn / hiện cả nhóm một lần */
14	export const pointLights = new THREE.Group();
15	
16	export function buildLights() {
17	  sun.castShadow = true;
18	  sun.shadow.mapSize.set(CONFIG.shadowMapSize, CONFIG.shadowMapSize);
19	  const s = sun.shadow.camera; s.left = -470; s.right = 470; s.top = 470; s.bottom = -470; s.near = 10; s.far = 2200;
20	  sun.shadow.camera.layers.enable(1);
21	  sun.shadow.bias = -0.0004; sun.shadow.normalBias = 0.6;
22	  scene.add(sun, hemi, moon, sun.target);
23	  moon.position.set(-600, 900, -400);
24	  // Đèn chiếu dọc Cầu Rồng ban đêm: vàng ấm xen xanh lam
25	  const xs = [-215, -130, -45, 45, 130, 215];
26	  xs.forEach((x, i) => {
27	    const l = new THREE.PointLight(i % 2 ? 0x4a8cff : 0xffb556, 0, 90, 1.6);
28	    l.position.set(x, deckY(x) + 10, i % 2 ? 9 : -9);
29	    l.userData.base = 350; l.userData.phase = i * 1.3;
30	    pointLights.add(l); bridgeLights.push(l);
31	  });
32	  fireLight = new THREE.PointLight(0xff7a2a, 0, 160, 1.5);
33	  pointLights.add(fireLight);
34	  pointLights.name = 'point-lights';
35	  scene.add(pointLights);
36	}
37	
38	/* Bộ đèn theo trạng thái (D-031). three bỏ đèn ẩn (visible = false) khỏi trạng thái đèn ⇒ shader không tính đèn đó cho từng điểm ảnh,
39	   và không vẽ shadow map khi sun ẩn. Đèn cường độ 0 vẫn tốn như đèn sáng (đo Intel Arc: 7 PointLight + moon ≈ 5 ms/khung ban ngày; bóng ban đêm ≈ 5,6 ms).
40	   Đổi bộ làm đổi số đèn trong program key: mỗi vật liệu giữ sẵn program của từng bộ (materialProperties.programs) nên chỉ là tra bảng,
41	   với điều kiện bộ đó đã biên dịch + vẽ hâm (core/prewarm.ts: lightState.ready; mặc định hâm nền sau khung đầu). Ngoại lệ có kiểm soát của quy tắc D-018 "không đổi program key khi đang chạy":
42	   chỉ ba bộ cố định dưới đây; mọi cách đổi số đèn khác vẫn cấm.
43	   - day:   sun hiện, moon + 7 PointLight ẩn — khi sun.intensity > 0, moon.intensity = 0 và mọi PointLight cường độ 0
44	   - night: sun ẩn (không lượt bóng, không lấy mẫu bóng), moon + 7 PointLight hiện — khi sun.intensity = 0 (đêm ≥ 0,87)
45	   - full:  tất cả hiện — còn lại: đang chuyển ngày ↔ đêm, rồng phun lửa ban ngày */
46	export type LightSet = 'day' | 'night' | 'full';
47	export const LIGHT_SETS: readonly LightSet[] = ['day', 'night', 'full'];
48	/* set: bộ đang dùng (lúc dựng mọi đèn đều hiện); mode: device.lightSets ('off' nếu trình duyệt không biên dịch song song được);
49	   ready: bộ đã biên dịch xong — stepLights chỉ chuyển sang bộ đã sẵn sàng, chưa thì ở 'full' (hình như nhau, chỉ chậm hơn). 'full' sẵn sàng sau prewarm */
50	export const lightState = { set: 'full' as LightSet, mode: device.lightSets, ready: { day: false, night: false, full: true } as Record<LightSet, boolean> };
51	export function applyLightSet(set: LightSet) {
52	  lightState.set = set;
53	  sun.visible = set !== 'night';
54	  moon.visible = set !== 'day';
55	  pointLights.visible = set !== 'day';
56	}
57	/* Mỗi khung: sau mọi chỗ ghi cường độ đèn (applyNight, updateWeather, updateEffects), trước khi vẽ; chỉ ghi visible khi bộ đổi */
58	export function stepLights() {
59	  let set: LightSet = 'full';
60	  if (sun.intensity <= 0) set = 'night';
61	  else if (moon.intensity <= 0) {
62	    let dark = true;
63	    const ls = pointLights.children;
64	    for (let i = 0; i < ls.length; i++) if ((ls[i] as THREE.PointLight).intensity > 0) { dark = false; break; }
65	    if (dark) set = 'day';
66	  }
67	  if (lightState.mode === 'off' || !lightState.ready[set]) set = 'full';
68	  if (set !== lightState.set) applyLightSet(set);
69	}
70	
71	/* Bóng đổ (D-018). Hai nguồn: nút "Bóng đổ" của người dùng (user) và bộ quản lý chất lượng (size = 0 là tắt, every = vẽ lại mỗi n khung).
72	   Không đổi sun.castShadow khi đang chạy: đổi nó làm số bóng trong define đổi ⇒ mọi vật liệu có ánh sáng biên dịch lại (giật hàng giây).
73	   Tắt: ngừng vẽ shadow map và xoá nó về trắng (độ sâu 1 = không vật nào che) ⇒ mặt nhận bóng sáng như khi không có bóng.
74	   Ngoại lệ: điện thoại khởi động ở bậc Thấp thì castShadow = false ngay từ đầu (đỡ lấy mẫu bóng mỗi điểm ảnh); bật lại sau đó thì biên dịch lại một lần.
75	   Bộ đèn night ẩn sun: three tự bỏ lượt bóng và lấy mẫu bóng; shadowState / stepShadows giữ nguyên nghĩa (map cũ còn đó, không ai đọc tới khi sun hiện lại). */
76	export const shadowState = { user: true, size: CONFIG.shadowMapSize, every: 1 };
77	const clearTmp = new THREE.Color();
78	let frame = 0, cleared = false;
79	function clearShadowMap() {
80	  const map = sun.shadow.map;
81	  if (!map) return;
82	  const rt = renderer.getRenderTarget(), alpha = renderer.getClearAlpha();
83	  renderer.getClearColor(clearTmp);
84	  renderer.setRenderTarget(map); renderer.setClearColor(0xffffff, 1); renderer.clear();
85	  renderer.setRenderTarget(rt); renderer.setClearColor(clearTmp, alpha);
86	}
87	/* Nút người dùng */
88	export function setShadows(on: boolean) { shadowState.user = on; }
89	/* Bộ quản lý chất lượng: cạnh shadow map (0 = tắt) và chu kỳ vẽ lại */
90	export function setShadowQuality(size: number, every: number) {
91	  shadowState.every = Math.max(1, every);
92	  if (size > 0 && size !== sun.shadow.mapSize.x) {
93	    sun.shadow.mapSize.set(size, size);
94	    if (sun.shadow.map) { sun.shadow.map.dispose(); sun.shadow.map = null; }   // three tạo lại map đúng cỡ ở lần vẽ bóng kế tiếp (cỡ map là uniform: không biên dịch lại)
95	  }
96	  shadowState.size = size;
97	  if (size > 0 && !sun.castShadow) sun.castShadow = true;   // chỉ xảy ra khi khởi động ở bậc Thấp trên điện thoại
98	}
99	/* Mỗi khung, trước khi vẽ */
100	export function stepShadows() {
101	  const on = shadowState.user && shadowState.size > 0 && sun.castShadow;
102	  if (on) {
103	    cleared = false;
104	    renderer.shadowMap.autoUpdate = shadowState.every <= 1;
105	    if (shadowState.every > 1) renderer.shadowMap.needsUpdate = !sun.shadow.map || frame % shadowState.every === 0;
106	    frame++;
107	    return;
108	  }
109	  renderer.shadowMap.autoUpdate = false;
110	  if (!cleared && sun.shadow.map) { clearShadowMap(); cleared = true; }
111	}
