1	// A/B xen kẽ trên GPU thật: mỗi cấu hình đo nhiều vòng, lấy trung vị. node ab.mjs <repo> [--w= --h=] [--night] [--view=bridge,view]
2	import { createRequire } from 'node:module';
3	import { pathToFileURL } from 'node:url';
4	import path from 'node:path';
5	
6	const repo = process.argv[2];
7	const arg = (k, d) => { const a = process.argv.find((x) => x.startsWith(`--${k}=`)); return a ? a.slice(k.length + 3) : d; };
8	const W = +arg('w', 1920), H = +arg('h', 1080), night = process.argv.includes('--night'), view = arg('view', '');
9	const require = createRequire(path.join(repo, 'package.json'));
10	const { chromium } = require('playwright');
11	const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
12	const srv = await lib.serveDir(path.join(repo, 'dist'));
13	const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
14	const { page, errors } = await lib.openApp(browser, srv.url, { width: W, height: H });
15	try {
16	  if (view) { const [b, v] = view.split(','); await lib.pickView(page, b, v); }
17	  if (night) { await page.evaluate(() => { const d = window.__app.dayNight; d.target = d.night = 1; }); }
18	  await lib.frames(page, 10);
19	  const res = await page.evaluate(async (night) => {
20	    const A = window.__app, R = A.renderer, gl = R.getContext(), px = new Uint8Array(4);
21	    const byName = (n) => { const l = []; A.scene.traverse((o) => { if (o.name === n && o.isMesh) l.push(o); }); return l; };
22	    const composer = null;
23	    const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
24	    const ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
25	    if (!ext) return { 'không có timer query': {} };
26	    const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
27	    const t = async (n = 12) => {
28	      draw(); draw();
29	      const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
30	      for (let i = 0; i < n; i++) draw();
31	      gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
32	      for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
33	      const ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
34	      return ns / 1e6 / n;
35	    };
36	    // lưới ẩn riêng trong lượt phản chiếu: bọc onBeforeRender của nước
37	    const water = A.scene.children.find((o) => o.material?.uniforms?.mirrorSampler);
38	    const wDraw = water.onBeforeRender; let hideInMirror = [];
39	    water.onBeforeRender = function (...a) { for (const o of hideInMirror) o.visible = false; wDraw.apply(this, a); for (const o of hideInMirror) o.visible = true; };
40	    const crown = byName('trees-shade-crown'), trunk = byName('trees-shade-trunk'), palmC = byName('trees-palm-crown'), palmT = byName('trees-palm-trunk'), cars = byName('traffic-city'), boats = byName('boats-river');
41	    const trees = [...crown, ...trunk, ...palmC, ...palmT];
42	    const all = []; A.scene.traverse((o) => { if (o.isMesh) all.push(o); });
43	    const shadowOff = (l) => { const s = l.map((o) => o.castShadow); l.forEach((o) => (o.castShadow = false)); return () => l.forEach((o, i) => (o.castShadow = s[i])); };
44	    const hide = (l) => { l.forEach((o) => (o.visible = false)); return () => l.forEach((o) => (o.visible = true)); };
45	    const lights = []; A.scene.traverse((o) => { if (o.isPointLight) lights.push(o); });
46	    const lightsOff = () => { lights.forEach((l) => (l.visible = false)); return () => lights.forEach((l) => (l.visible = true)); };
47	    const both = (...f) => () => { const u = f.map((x) => x()); return () => u.forEach((x) => x()); };
48	    const noShadow = () => { stop = true; return () => (stop = false); };
49	    let stop = false; const ss = R.shadowMap; let au = true; Object.defineProperty(ss, 'autoUpdate', { get: () => !stop && au, set: (v) => (au = v) });
50	    const noMirror = () => { A.reflectState.every = 0; return () => (A.reflectState.every = 1); };
51	    const cfgs = {
52	      'gốc': () => () => {},
53	      'bỏ PointLight': lightsOff,
54	      'tắt bóng': noShadow,
55	      'tắt phản chiếu': noMirror,
56	      'tắt bóng + phản chiếu': both(noShadow, noMirror),
57	      'cây: bỏ khỏi phản chiếu': () => { hideInMirror = trees; return () => (hideInMirror = []); },
58	      'cây: không đổ bóng': () => shadowOff(trees),
59	      'xe phố: không đổ bóng': () => shadowOff(cars),
60	      'cây: ẩn hẳn': () => hide(trees),
61	      'xe phố: ẩn hẳn': () => hide(cars),
62	      'ẩn nước': () => hide([water]),
63	      'bỏ PointLight + tắt bóng + phản chiếu': both(lightsOff, noShadow, noMirror),
64	      'bỏ PointLight + cây khỏi phản chiếu + xe không bóng': both(lightsOff, () => { hideInMirror = trees; return () => (hideInMirror = []); }, () => shadowOff(cars))
65	    };
66	    const out = {}, tri = {};
67	    for (const k in cfgs) out[k] = [];
68	    for (let round = 0; round < 5; round++) for (const k in cfgs) {
69	      const undo = cfgs[k](); await t(3);
70	      out[k].push(await t(12)); tri[k] = [R.info.render.calls, R.info.render.triangles];
71	      undo();
72	      
73	    }
74	    const med = (a) => a.slice().sort((x, y) => x - y)[a.length >> 1];
75	    const rows = {};
76	    for (const k in out) rows[k] = { ms: +med(out[k]).toFixed(2), min: +Math.min(...out[k]).toFixed(2), max: +Math.max(...out[k]).toFixed(2), calls: tri[k][0], tris: tri[k][1] };
77	    return rows;
78	  }, night);
79	  console.log(`khung ${W}x${H} ${night ? 'ĐÊM' : 'ngày'} ${view}`);
80	  console.table(res);
81	  if (errors.length) console.log('LỖI console:', errors);
82	} finally { await browser.close(); srv.close(); }
