1	// Tiện ích chung cho các script kiểm tra: server tĩnh + mở trang bằng Chromium (Playwright).
2	import { fileURLToPath } from 'node:url';
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import path from 'node:path';
6	import { chromium } from 'playwright';
7	
8	const THREE_DIR = fileURLToPath(new URL('../node_modules/three/', import.meta.url));
9	const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.svg': 'image/svg+xml', '.mp3': 'audio/mpeg', '.png': 'image/png' };
10	
11	/** Server tĩnh tối giản cho một thư mục (theo symlink). Trả về { url, close }. */
12	export function serveDir(dir) {
13	  const root = path.resolve(dir);
14	  const server = http.createServer((req, res) => {
15	    let p = decodeURIComponent(new URL(req.url, 'http://x').pathname);
16	    if (p.endsWith('/')) p += 'index.html';
17	    let file = path.join(root, p);
18	    if (!file.startsWith(root)) { res.writeHead(403); return res.end(); }
19	    // Bản gốc nạp three từ /three/… : nếu thư mục không có thì lấy từ node_modules/three của project
20	    if (p.startsWith('/three/') && !fs.existsSync(file)) file = path.join(THREE_DIR, p.slice('/three/'.length));
21	    fs.readFile(file, (err, data) => {
22	      if (err) { res.writeHead(404); return res.end('not found'); }
23	      res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
24	      res.end(data);
25	    });
26	  });
27	  return new Promise((ok) => server.listen(0, '127.0.0.1', () => ok({ url: `http://127.0.0.1:${server.address().port}/`, close: () => server.close() })));
28	}
29	
30	export async function launch() {
31	  return chromium.launch({
32	    executablePath: process.env.CHROMIUM_PATH || undefined,
33	    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
34	  });
35	}
36	
37	/** Mở trang với ?test, chặn font Google (không cần cho kiểm tra), chờ khung hình đầu. */
38	export async function openApp(browser, url, { width = 480, height = 270, mobile = false } = {}) {
39	  const page = await browser.newPage(mobile ? { viewport: { width, height }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : { viewport: { width, height } });
40	  const errors = []; page.setDefaultTimeout(240000);
41	  page.on('pageerror', (e) => errors.push(String(e)));
42	  page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|ERR_FAILED|net::/.test(m.text())) errors.push(m.text()); });
43	  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
44	  await page.goto(url + (url.includes('?') ? '&' : '?') + 'test', { waitUntil: 'load', timeout: 180000 });
45	  await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
46	  return { page, errors };
47	}
48	
49	/** Chờ n khung hình. */
50	export const frames = (page, n = 2) => page.evaluate((n) => new Promise((ok) => { let i = 0; const f = () => (++i >= n ? ok() : requestAnimationFrame(f)); requestAnimationFrame(f); }), n);
51	
52	/** Chờ hiệu ứng bay camera (flyTo) kết thúc. */
53	// Phần mềm dựng hình (SwiftShader) rất chậm nên tua nhanh: đẩy tiến độ bay gần tới đích để khung hình kế tiếp hoàn tất.
54	export async function waitFlight(page) {
55	  await page.evaluate(() => { const f = window.__app.cam.flight; if (window.__app.cam.mode === 'fly') f.t = Math.max(f.t, 0.999); });
56	  await page.waitForFunction(() => window.__app.cam.mode !== 'fly', null, { timeout: 240000 });
57	}
58	
59	/** Bấm một phần tử: ở chế độ gọn thì mở đúng tờ chứa nó trước (reveal), chờ 1 khung, rồi bấm. */
60	export async function tap(page, sel) {
61	  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
62	  await frames(page, 1);
63	  await page.click(sel);
64	}
65	
66	/** Như tap nhưng cho ô chọn (select). */
67	export async function pick(page, sel, value) {
68	  await page.evaluate((s) => window.__app.ui?.reveal(document.querySelector(s)), sel);
69	  await frames(page, 1);
70	  await page.selectOption(sel, value);
71	}
72	
73	/** Chọn cầu rồi bấm nút góc nhìn. */
74	export async function pickView(page, bridge, view) {
75	  await tap(page, `button[data-bridge="${bridge}"]`);
76	  await waitFlight(page);
77	  await tap(page, `button[data-view="${view}"]`);
78	  await waitFlight(page);
79	}
