1	// Đo biên dịch nền bộ đèn trên GPU thật: node bgwarm.mjs <repo> <distDir> <query>   (query vd "perf&lightsets=bg", "perf")
2	import { createRequire } from 'node:module';
3	import { pathToFileURL } from 'node:url';
4	import path from 'node:path';
5	
6	const repo = process.argv[2], dist = process.argv[3], query = process.argv[4] || 'perf';
7	const require = createRequire(path.join(repo, 'package.json'));
8	const { chromium } = require('playwright');
9	const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
10	const srv = await lib.serveDir(dist);
11	const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
12	const { page, errors } = await lib.openApp(browser, srv.url + '?' + query, { width: 1920, height: 1080 });
13	const J = (x) => JSON.stringify(x);
14	try {
15	  const st = await page.evaluate(() => ({ firstFrameMs: Math.round(window.__app.perf.firstFrameMs), programs: window.__app.renderer.info.programs.length, set: window.__app.lights?.set, mode: window.__app.lights?.mode, ext: !!window.__app.renderer.extensions.has('KHR_parallel_shader_compile') }));
16	  console.log('khởi động', J(st));
17	  // ghi mỗi khung: khoảng cách, bộ đèn, số program
18	  await page.evaluate(() => {
19	    const A = window.__app; const rec = (window.__rec = []); let last = performance.now();
20	    const f = () => { const t = performance.now(); rec.push([t - last, A.lights?.set, A.renderer.info.programs.length, A.lights?.ready?.day, A.lights?.ready?.night, t]); last = t; requestAnimationFrame(f); };
21	    requestAnimationFrame(f); A.perf.reset();
22	  });
23	  const take = () => page.evaluate(() => { const r = window.__rec.slice(); window.__rec.length = 0; return r; });
24	  const summary = (label, r) => {
25	    const dts = r.map((x) => x[0]); const max = Math.max(...dts); const sorted = dts.slice().sort((a, b) => a - b);
26	    const long = r.filter((x) => x[0] > 50).map((x) => `${x[0].toFixed(0)}ms@${x[1]}/p${x[2]}`);
27	    console.log(`${label.padEnd(26)} khung ${r.length}, trung vị ${sorted[sorted.length >> 1]?.toFixed(1)} ms, dài nhất ${max.toFixed(1)} ms, program ${r[0]?.[2]}→${r.at(-1)?.[2]}; khung > 50 ms: ${long.slice(0, 12).join(' ')}`);
28	  };
29	  const setNight = (n) => page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
30	  const hasSets = st.mode !== undefined;
31	  if (query.includes('lightsets=bg')) {
32	    const t0 = await page.evaluate(() => performance.now());
33	    const tDay = await page.waitForFunction(() => window.__app.lights.ready.day && performance.now(), null, { timeout: 120000, polling: 50 }).then((h) => h.jsonValue());
34	    const tNight = await page.waitForFunction(() => window.__app.lights.ready.night && performance.now(), null, { timeout: 120000, polling: 50 }).then((h) => h.jsonValue());
35	    await lib.frames(page, 20);
36	    const r = await take();
37	    const iDay = r.findIndex((x) => x[1] === 'day');
38	    const warmPart = r.filter((x) => x[5] < tNight - 0);
39	    summary('hâm nền (tới ready.night)', warmPart);
40	    console.log(`ready.day sau ${(tDay - t0).toFixed(0)} ms, ready.night sau ${(tNight - t0).toFixed(0)} ms (tính từ lúc mở trang xong); perf.maxs:`, J(await page.evaluate(() => window.__app.perf.maxs)));
41	    if (iDay >= 0) summary('chuyển full→day lần đầu', r.slice(Math.max(0, iDay - 1), iDay + 15)); else console.log('chưa chuyển sang day!');
42	    summary('sau ready (20 khung)', r.slice(-20));
43	  } else { await lib.frames(page, 120); summary('120 khung đầu sau mở', await take()); }
44	  await page.evaluate(() => window.__app.perf.reset());
45	  const step = async (label, fn, n = 30) => { await take(); await fn(); await lib.frames(page, n); const r = await take(); summary(label, r); return r; };
46	  await step('đêm lần đầu', () => setNight(1));
47	  await step('ngày lần 2', () => setNight(0));
48	  await step('đêm lần 2', () => setNight(1));
49	  await step('ngày lần 3', () => setNight(0));
50	  await step('bay Thuận Phước (ngày)', () => lib.pickView(page, 'tp', 'tpBay'), 10);
51	  await lib.frames(page, 30);
52	  await step('về Cầu Rồng overview', () => lib.pickView(page, 'dragon', 'overview'), 10);
53	  console.log('perf.maxs:', J(await page.evaluate(() => window.__app.perf.maxs)));
54	  // lệnh vẽ + bộ đèn góc mặc định (gọi lại góc mặc định khó: dùng overview như perf-check) — ngày / đêm
55	  const info = async () => { await lib.frames(page, 8); return page.evaluate(() => ({ set: window.__app.lights?.set, calls: window.__app.renderer.info.render.calls, tris: window.__app.renderer.info.render.triangles, programs: window.__app.renderer.info.programs.length })); };
56	  await setNight(0); console.log('overview ngày', J(await info()));
57	  await setNight(1); console.log('overview đêm', J(await info()));
58	  await setNight(0);
59	  if (hasSets && st.mode !== 'off') {
60	    const gpu = () => page.evaluate(async () => {
61	      const A = window.__app, R = A.renderer, gl = R.getContext();
62	      const ext = gl.getExtension('EXT_disjoint_timer_query_webgl2'); if (!ext) return -1;
63	      const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
64	      const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
65	      draw(); draw();
66	      const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
67	      for (let i = 0; i < 12; i++) draw();
68	      gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
69	      for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
70	      const ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
71	      return ns / 1e6 / 12;
72	    });
73	    const force = (full) => page.evaluate((full) => { const L = window.__app.lights; L.ready.day = L.ready.night = !full; }, full);
74	    const out = {};
75	    for (let r = 0; r < 5; r++) for (const n of [0, 1]) for (const full of [false, true]) {
76	      await force(full); await setNight(n); await lib.frames(page, 8);
77	      const k = `${n ? 'đêm' : 'ngày'} ${full ? 'ép full' : 'bộ thật'}`;
78	      (out[k] ||= []).push([await gpu(), await page.evaluate(() => window.__app.lights.set)]);
79	    }
80	    await force(false);
81	    const med = (a) => a.map((x) => x[0]).sort((x, y) => x - y)[a.length >> 1];
82	    for (const k in out) console.log(`GPU ${k.padEnd(14)} trung vị ${med(out[k]).toFixed(2)} ms (bộ ${out[k][0][1]})`);
83	  }
84	  console.log('program cuối', await page.evaluate(() => window.__app.renderer.info.programs.length));
85	  if (errors.length) console.log('LỖI console:', errors);
86	} finally { await browser.close(); srv.close(); }
